'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var isAlmostSameValue = require( '@stdlib/number/float32/base/assert/is-almost-same-value' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var randu = require( '@stdlib/random/base/randu' );
var NINF = require( '@stdlib/constants/float32/ninf' );
var tryRequire = require( '@stdlib/utils/try-require' );


// VARIABLES //

var boxcoxf = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( boxcoxf instanceof Error )
};


// FIXTURES //

var mediumPositive = require( './fixtures/python/medium_positive.json' );
var smallPositive = require( './fixtures/python/small_positive.json' );
var tiny = require( './fixtures/python/tiny.json' );
var tinyLambda = require( './fixtures/python/tiny_lambda.json' );


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof boxcoxf, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns `NaN` if provided `NaN`', opts, function test( t ) {
	var b;

	b = boxcoxf( NaN, 1.0 );
	t.strictEqual( isnanf( b ), true, 'returns expected value' );

	b = boxcoxf( 1.0, NaN );
	t.strictEqual( isnanf( b ), true, 'returns expected value' );

	b = boxcoxf( NaN, NaN );
	t.strictEqual( isnanf( b ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns `-Infinity` if lambda is negative and `x` is +-0', opts, function test( t ) {
	var lambda;
	var b;
	var i;

	for ( i = 0; i < 1e3; i++ ) {
		lambda = f32( -1.0 * ( (randu()*100.0) + 1.0 ) );

		b = boxcoxf( +0.0, lambda );
		t.strictEqual( b, NINF, 'returns -Infinity when lambda is negative and `x` is positive zero' );

		b = boxcoxf( -0.0, lambda );
		t.strictEqual( b, NINF, 'returns -Infinity when lambda is negative and `x` is negative zero' );
	}
	t.end();
});

tape( 'the function returns `NaN` if `x` is negative', opts, function test( t ) {
	var b;
	var x;
	var y;
	var i;

	for ( i = 0; i < 1e3; i++ ) {
		x = f32( -1.0 * ( (randu()*100.0) + 1.0 ) );
		y = f32( randu() * 10.0 );
		b = boxcoxf( x, y );
		t.strictEqual( isnanf( b ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function computes a one-parameter Box-Cox transformation for positive medium numbers', opts, function test( t ) {
	var expected;
	var x;
	var y;
	var b;
	var e;
	var i;

	expected = mediumPositive.expected;
	x = mediumPositive.x;
	y = mediumPositive.y;
	for ( i = 0; i < expected.length; i++ ) {
		b = boxcoxf( x[ i ], y[ i ] );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValue( b, e, 10 ), true, 'within 10 ULPs. x: '+x[i]+'. y: '+y[i]+'. b: '+b+'. E: '+e+'.' );
	}
	t.end();
});

